ALTER TABLE "class_record_scores" DROP CONSTRAINT "class_record_score_status_valid";--> statement-breakpoint
ALTER TABLE "class_record_scores" ADD CONSTRAINT "class_record_score_status_valid" CHECK (("class_record_scores"."status" = 'recorded' AND "class_record_scores"."score" IS NOT NULL AND "class_record_scores"."score" >= 0 AND "class_record_scores"."bonus_points" >= 0 AND ("class_record_scores"."bonus_points" = 0 OR ("class_record_scores"."bonus_reason" IS NOT NULL AND length(trim("class_record_scores"."bonus_reason")) > 0))) OR ("class_record_scores"."status" = 'excused' AND "class_record_scores"."score" IS NULL AND "class_record_scores"."bonus_points" = 0 AND length(trim("class_record_scores"."reason")) > 0 AND "class_record_scores"."reason" IS NOT NULL) OR ("class_record_scores"."status" = 'excused_with_score' AND "class_record_scores"."score" IS NOT NULL AND "class_record_scores"."score" >= 0 AND "class_record_scores"."bonus_points" = 0 AND length(trim("class_record_scores"."reason")) > 0 AND "class_record_scores"."reason" IS NOT NULL));